1	export type Item = {
2	  type: string;
3	};
4	
5	export type Scenario = {
6	  customer: { yearsWithMHPCO: number };
7	  steps: { op: string; items: Item[] }[];
8	};
9	
10	export type ScenarioResult = {
11	  results: { premium: number }[];
12	};
