14	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
15	  sword: 100,
16	  amulet: 60,
17	  staff: 80,
18	  potion: 40,
19	  rune: 25,
20	};
21	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
22	const PROCESSING_FEE = 5;
23	
24	const percentOf = (amount: number, percent: number): number =>
25	  (amount * percent) / 100;
26	
27	const roundInMHPCOsFavour = (premium: number): number => Math.ceil(premium);
28	
29	const BLOCK_SIZE = 3;
30	const BLOCK_BASE_PREMIUM = 60;
31	
32	const countByType = (items: Item[]): Map<string, number> => {
33	  const counts = new Map<string, number>();
34	  for (const item of items) {
35	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
36	  }
37	  return counts;
38	};
39	
40	const basePremiumForGroup = (type: string, count: number): number =>
41	  count === BLOCK_SIZE
42	    ? BLOCK_BASE_PREMIUM
43	    : count * BASE_PREMIUM_BY_ITEM_TYPE[type];
44	
45	const policyBasePremium = (items: Item[]): number =>
46	  [...countByType(items)]
47	    .map(([type, count]) => basePremiumForGroup(type, count))
48	    .reduce((total, groupPremium) => total + groupPremium, 0);
49	
50	const quotePremium = (items: Item[]): number => {
51	  const basePremium = policyBasePremium(items);
52	  const withFirstInsuranceSurcharge =
53	    basePremium + percentOf(basePremium, FIRST_INSURANCE_SURCHARGE_PERCENT);
54	  return roundInMHPCOsFavour(withFirstInsuranceSurcharge + PROCESSING_FEE);
55	};
56	
57	export const runScenario = (scenario: Scenario): ScenarioResult => ({
58	  results: scenario.steps.map((step) => ({
59	    premium: quotePremium(step.items),
60	  })),
61	});
